// 包含必要头文件 # define WSMAN_API_VERSION_1_0 # include // 当客户端对资源调用Get操作时会调用服务端的WSManProvGet函数 extern "C" __declspec(dllexport) void WSManProvGet (WSMAN_PLUGIN_REQUEST * request) { WSMAN_DATA data; data.type = WSMAN_DATA_TYPE_TEXT; // 输出格式为XML，真的是很麻烦啊~ data.text.buffer = L" 
" " Test WinRMPlugin 
" " Jonathan 
" " Hello! 
" " " ; data.text.bufferLength = 163 ; // 输出结果 WSManPluginObjectResult(request, 0 , &data); // 完成当前Get操作 WSManPluginOperationComplete(request, 0 , 0 , nullptr ); }
